  "After you submit, your roommate has a limited time to accept. Each of you pays your own deposit; both applications reach the dormitory office together once both deposits are paid. If the invitation is declined or not answered, invite someone else or continue alone.": "Sau khi bạn nộp đơn, bạn cùng phòng có một khoảng thời gian để chấp nhận. Mỗi người tự đóng tiền đặt cọc; hai đơn cùng đến văn phòng ký túc xá khi cả hai đã đóng cọc. Nếu lời mời bị từ chối hoặc không được trả lời, hãy mời người khác hoặc tiếp tục một mình.",
