  "I agree that CampusStay uses my gender, major and hometown to match roommates for {term}.": "Tôi đồng ý để CampusStay dùng giới tính, ngành và quê quán của tôi để ghép bạn cùng phòng cho {term}.",
  "I agree that CampusStay uses my gender, major and hometown to match roommates.": "Tôi đồng ý để CampusStay dùng giới tính, ngành và quê quán của tôi để ghép bạn cùng phòng.",
  "I have read the dormitory rules and the Privacy Notice.": "Tôi đã đọc nội quy ký túc xá và Thông báo về quyền riêng tư.",
