  "Privacy Notice": "Thông báo về quyền riêng tư",
  "CampusStay processes your name, student code, gender, major, cohort, hometown and contact details to review your application, match roommates and assign a room and bed.": "CampusStay xử lý họ tên, mã sinh viên, giới tính, ngành, khóa, quê quán và thông tin liên hệ của bạn để xét đơn, ghép bạn cùng phòng và xếp phòng, giường.",
  "Matching data (gender, major, hometown) is used only for the term you apply for. The dormitory office keeps application records for the period required by FPT University regulations, then deletes them.": "Dữ liệu ghép phòng (giới tính, ngành, quê quán) chỉ dùng cho học kỳ bạn đăng ký. Văn phòng ký túc xá lưu đơn đăng ký trong thời gian theo quy định của Đại học FPT, sau đó xóa.",
  "You can ask the dormitory office to see, correct or withdraw consent for your data at any time, as set out in the Personal Data Protection Law 91/2025/QH15 and Decree 356/2025/NĐ-CP.": "Bạn có thể yêu cầu văn phòng ký túc xá cho xem, sửa hoặc rút lại sự đồng ý đối với dữ liệu của mình bất cứ lúc nào, theo Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15 và Nghị định 356/2025/NĐ-CP.",
