  "Staff of the blocks in your scope, the work each person holds and who is on duty. Open a person's work to move it to someone else. Duty follows sign-in: staff are on duty while signed in and go off when they sign out or stop using the app for a while.": "Nhân viên của các tòa trong phạm vi của bạn, công việc mỗi người đang giữ và ai đang trực. Mở công việc của một người để chuyển cho người khác. Ca trực theo đăng nhập: nhân viên đang trực khi đăng nhập và hết ca khi đăng xuất hoặc không dùng ứng dụng một thời gian.",
