  "The shifts your Manager planned for you this week and next week, and the work they gave you. Outside your shifts or this work, a change asks you to confirm and is marked for your Manager.": "Ca làm Quản lý xếp cho bạn trong tuần này và tuần tới, cùng các công việc được phân. Ngoài ca hoặc ngoài các việc này, mỗi thao tác thay đổi sẽ cần bạn xác nhận và được đánh dấu cho Quản lý.",
  "No shift this week": "Tuần này chưa có ca",
