  "A new maintenance or room-change request goes to the person its routing rule names while they are on duty, else to the rule’s fallback.": "Yêu cầu bảo trì hoặc đổi phòng mới được chuyển cho người mà quy tắc phân công chỉ định khi họ đang trực, nếu không thì cho người dự phòng của quy tắc.",
